// Live CircuitJS simulation for tool pages.
// Templates public/sim/<name>.txt are generated by schematics/gen.py from the same Python circuit
// definitions as the KiCad schematics (schematics/circuitjs.py). Header lines:
//   # param R1 1000          default (SI units); tool calc() overrides via out.simParams
//   # let T = 0.693*(R1+2*R2)*C1
// and ${expr} placeholders in the circuit lines. This module must stay importable in node (tests).

const FUNCS = {
  min: Math.min, max: Math.max, round: (x) => Math.floor(x + 0.5), floor: Math.floor, ceil: Math.ceil,
  log: Math.log, log10: Math.log10, exp: Math.exp, sqrt: Math.sqrt, abs: Math.abs, pow: Math.pow, si,
};
const CONST = { PI: Math.PI };

/** compact SI text for labels in the circuit (2.5M, 470n …), mirrors circuitjs._si */
export function si(x) {
  if (x === 0) return '0';
  for (const [p, f] of [['G', 1e9], ['M', 1e6], ['k', 1e3], ['', 1], ['m', 1e-3], ['µ', 1e-6], ['n', 1e-9], ['p', 1e-12]]) {
    if (Math.abs(x) >= f * 0.9995) return String(+(x / f).toPrecision(3)) + p;
  }
  return String(+x.toPrecision(3));
}

/** tiny arithmetic evaluator: numbers, names, + - * / ** ( ), unary -, function calls */
export function evalExpr(src, env) {
  const toks = src.match(/\d*\.?\d+(?:[eE][-+]?\d+)?|[A-Za-z_]\w*|\*\*|[-+*/(),]/g) || [];
  if (toks.join('') !== src.replace(/\s+/g, '')) throw new Error(`bad expression: ${src}`);
  let i = 0;
  const peek = () => toks[i];
  const take = (t) => { if (toks[i] !== t) throw new Error(`expected ${t} in ${src}`); i++; };
  function primary() {
    const t = toks[i++];
    if (t === undefined) throw new Error(`unexpected end: ${src}`);
    if (t === '(') { const v = sum(); take(')'); return v; }
    if (t === '-') return -power();
    if (t === '+') return power();
    if (/^[\d.]/.test(t)) return parseFloat(t);
    if (peek() === '(') {
      const f = FUNCS[t]; if (!f) throw new Error(`unknown function ${t}`);
      i++; const args = [];
      if (peek() !== ')') { args.push(sum()); while (peek() === ',') { i++; args.push(sum()); } }
      take(')'); return f(...args);
    }
    if (t in env) return env[t];
    if (t in CONST) return CONST[t];
    throw new Error(`unknown name ${t}`);
  }
  function power() { const b = primary(); if (peek() === '**') { i++; return b ** unary(); } return b; }
  function unary() { if (peek() === '-') { i++; return -unary(); } return power(); }
  function prod() { let v = unary(); while (peek() === '*' || peek() === '/') { const o = toks[i++]; const r = unary(); v = o === '*' ? v * r : v / r; } return v; }
  function sum() { let v = prod(); while (peek() === '+' || peek() === '-') { const o = toks[i++]; const r = prod(); v = o === '+' ? v + r : v - r; } return v; }
  const v = sum();
  if (i !== toks.length) throw new Error(`trailing tokens in ${src}`);
  return v;
}

/** number -> token CircuitJS parses (Java Double / Integer) */
const numTok = (v) => (typeof v === 'string' ? v : Number.isInteger(v) ? String(v) : String(+v.toPrecision(12)));

/** template text + simParams -> plain CircuitJS circuit text */
export function renderSim(text, simParams = {}) {
  const env = {}, lets = [], body = [];
  for (const line of text.split(/\r?\n/)) {
    let m;
    if ((m = line.match(/^#\s*param\s+(\w+)\s+(\S+)/))) { env[m[1]] = parseFloat(m[2]); continue; }
    if ((m = line.match(/^#\s*let\s+(\w+)\s*=\s*(.+)$/))) { lets.push([m[1], m[2]]); continue; }
    if (line.startsWith('#') || !line.trim()) continue;
    body.push(line);
  }
  for (const [k, v] of Object.entries(simParams)) if (typeof v === 'number' && isFinite(v)) env[k] = v;
  for (const [k, e] of lets) if (!(k in simParams)) env[k] = evalExpr(e, env);
  return body.map((l) => l.replace(/\$\{([^}]*)\}/g, (_, e) => {
    const v = evalExpr(e, env);
    if (typeof v === 'number' && !isFinite(v)) throw new Error(`${e} = ${v}`);
    return numTok(v);
  })).join('\n') + '\n';
}

export const EETREE_CIRCUITJS = 'https://www.eetree.cn/circuitjs/circuitjs.html';

/** CircuitJS URL with the circuit in ?cct= (CirSim reads cct, replaces %24 with $) */
export function simUrl(base, circuit) {
  return `${base}${base.includes('?') ? '&' : '?'}cct=${encodeURIComponent(circuit)}`;
}

// ------------------------------------------------------------------ DOM part
const cache = {};
function fetchTemplate(url) {
  cache[url] ??= fetch(url).then((r) => { if (!r.ok) throw new Error(r.status + ' ' + url); return r.text(); });
  return cache[url];
}

/** which sim applies now: tool.sim (string | {mode: name}) or out.sim; only when that schematic is displayed */
function simName(tool, out, mode, curSch) {
  let s = out.sim ?? (tool.sim && typeof tool.sim === 'object' ? tool.sim[mode] : tool.sim);
  if (!s || !out.simParams) return null;
  return s === curSch ? s : null;
}

/** called by engine.update(); cheap no-op for tools without sim */
export function syncSim(root, tool, out, mode) {
  if (!tool.sim) return;
  const fig = root.querySelector('#schfig');
  if (!fig) return;
  const st = (fig._sim ??= { tab: 'sch' });
  const name = simName(tool, out, mode, fig.dataset.cur);
  if (!name) { if (st.tabs) { st.tabs.hidden = true; show(fig, st, 'sch'); } return; }
  if (!st.tabs) build(fig, st);
  st.tabs.hidden = false;
  st.name = name;
  st.params = out.simParams;
  if (st.tab === 'sim') refresh(fig, st);
  else st.dirty = true;
}

function build(fig, st) {
  const card = fig.closest('section');
  const tabs = document.createElement('div');
  tabs.className = 'seg sim-tabs';
  tabs.setAttribute('role', 'tablist');
  tabs.innerHTML = '<button role="tab" data-t="sch" aria-selected="true">KiCad 原理图</button><button role="tab" data-t="sim" aria-selected="false">实时仿真</button>';
  card.querySelector('h2').after(tabs);
  const pane = document.createElement('div');
  pane.className = 'sim-pane';
  pane.hidden = true;
  fig.after(pane);
  st.tabs = tabs; st.pane = pane;
  tabs.addEventListener('click', (e) => {
    const b = e.target.closest('button[data-t]');
    if (b) show(fig, st, b.dataset.t);
  });
}

function show(fig, st, t) {
  st.tab = t;
  if (!st.tabs) return;
  st.tabs.querySelectorAll('button').forEach((b) => b.setAttribute('aria-selected', String(b.dataset.t === t)));
  fig.hidden = t !== 'sch';
  st.pane.hidden = t !== 'sim';
  if (t === 'sim' && (st.dirty || !st.url)) refresh(fig, st);
}

function config(fig) {
  const base = fig.dataset.cjs || EETREE_CIRCUITJS;
  const abs = new URL(base, location.href);
  // X-Frame-Options SAMEORIGIN on eetree.cn: embed only when CircuitJS is served from this origin
  const embed = abs.origin === location.origin && (location.hostname.endsWith('eetree.cn') || fig.dataset.cjsEmbed === '1');
  const open = embed ? abs.href : (/^https?:/.test(base) ? base : EETREE_CIRCUITJS);
  return { embed, base: abs.href, open };
}

let timer = 0;
function refresh(fig, st) {
  clearTimeout(timer);
  timer = setTimeout(() => render(fig, st), st.url ? 400 : 0);
}

async function render(fig, st) {
  st.dirty = false;
  const cfg = config(fig);
  let circuit;
  try {
    const tpl = await fetchTemplate(`${fig.dataset.simBase}${st.name}.txt`);
    // SCOPE_W: approx. scope width in px (templates may use it to fit e.g. one full sweep on screen)
    const w = cfg.embed ? st.pane.clientWidth || fig.clientWidth : 0;
    circuit = renderSim(tpl, { SCOPE_W: w ? Math.max(160, Math.round(w * 0.68)) : 600, ...st.params });
  } catch (e) {
    console.error(e);
    st.pane.innerHTML = `<p class="msg warn">仿真电路加载失败：${String(e.message).replace(/[<&]/g, '')}</p>`;
    return;
  }
  const url = simUrl(cfg.embed ? cfg.base : cfg.open, circuit);
  if (url === st.url) return;
  st.url = url;
  const openUrl = simUrl(cfg.open, circuit);
  if (!cfg.embed) {
    st.pane.innerHTML = `<div class="sim-ext"><p>电路已按当前计算结果生成，可在电子森林 CircuitJS 中实时仿真：修改元件值、点击开关、观察示波器波形。</p>
<a class="btn primary" href="${openUrl}" target="_blank" rel="noopener">在电子森林 CircuitJS 中打开仿真 ↗</a>
<small>部署在 www.eetree.cn/tools 时，仿真会直接嵌入本页。</small></div>`;
    return;
  }
  const frame = st.pane.querySelector('iframe');
  if (frame) { swapCircuit(frame, url, circuit); setLinks(st, openUrl); return; }
  const phone = window.matchMedia('(max-width: 600px)').matches;
  st.pane.innerHTML = `<div class="sim-box"><div class="sim-frame">${phone && !st.tapped ? '<button class="sim-tap" type="button">▶ 点击加载实时仿真<small>CircuitJS，约 1 MB</small></button>' : ''}</div>
<div class="sim-bar"><span>CircuitJS 电路仿真 · 元件值随计算结果自动更新</span><button class="btn" data-fs type="button">全屏</button><a class="btn" data-open target="_blank" rel="noopener">新窗口 ↗</a></div></div>`;
  setLinks(st, openUrl);
  const box = st.pane.querySelector('.sim-frame');
  const load = () => {
    st.tapped = true;
    const f = document.createElement('iframe');
    f.title = 'CircuitJS 电路仿真';
    f.loading = 'lazy';
    f.allow = 'fullscreen';
    f.src = st.url;
    box.replaceChildren(f);
  };
  const tap = box.querySelector('.sim-tap');
  if (tap) tap.addEventListener('click', load); else load();
  st.pane.querySelector('[data-fs]').addEventListener('click', () => {
    const el = st.pane.querySelector('.sim-box');
    if (el.requestFullscreen) el.requestFullscreen().catch(() => window.open(st.url, '_blank'));
    else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
    else window.open(st.url, '_blank');
  });
}

function setLinks(st, href) {
  const a = st.pane.querySelector('[data-open]');
  if (a) a.href = href;
}

/** same-origin frame: load the new circuit through the CircuitJS1 JS API (no page reload); else reload */
function swapCircuit(frame, url, circuit) {
  try {
    const w = frame.contentWindow;
    const api = w?.CircuitJS1 || w?.frames?.[0]?.CircuitJS1;
    if (api?.importCircuit) { api.importCircuit(circuit, false); return; }
  } catch { /* cross-origin wrapper: fall through */ }
  frame.src = url;
}

// ------------------------------------------------------------------ case gallery pages (/cases/<name>/)
/** URL of a built-in CircuitJS example (CirSim reads ?startCircuit=<file> from its circuits/ folder) */
export function caseUrl(base, file) {
  return `${base}${base.includes('?') ? '&' : '?'}startCircuit=${encodeURIComponent(file)}`;
}

/** live simulation panel of a case page: <div id="casesim" data-cjs=".." data-file="x.txt" [data-cjs-embed="1"]> */
export function mountCaseSim(el) {
  if (!el) return;
  const cfg = config(el);
  const file = el.dataset.file;
  const openUrl = caseUrl(cfg.open, file);
  if (!cfg.embed) {
    el.innerHTML = `<div class="sim-ext"><p>本电路是 CircuitJS 内置示例，可在电子森林 CircuitJS 中实时仿真：拖动滑块、点击开关、观察电流动画和示波器波形。</p>
<a class="btn primary" href="${openUrl}" target="_blank" rel="noopener">在电子森林 CircuitJS 中打开仿真 ↗</a>
<small>部署在 www.eetree.cn 时，仿真会直接嵌入本页。</small></div>`;
    return;
  }
  const url = caseUrl(cfg.base, file);
  el.innerHTML = `<div class="sim-box"><div class="sim-frame"><button class="sim-tap" type="button">▶ 点击加载实时仿真<small>CircuitJS，约 1 MB</small></button></div>
<div class="sim-bar"><span>CircuitJS 电路仿真 · 可直接点击开关、拖动滑块</span><button class="btn" data-fs type="button">全屏</button><a class="btn" data-open target="_blank" rel="noopener" href="${url}">新窗口 ↗</a></div></div>`;
  const box = el.querySelector('.sim-frame');
  const load = () => {
    if (box.querySelector('iframe')) return;
    const f = document.createElement('iframe');
    f.title = 'CircuitJS 电路仿真';
    f.allow = 'fullscreen';
    f.src = url;
    box.replaceChildren(f);
  };
  box.querySelector('.sim-tap').addEventListener('click', load);
  // desktop: load when the panel scrolls into view; phones: tap to load (saves ~1 MB)
  if (!window.matchMedia('(max-width: 600px)').matches && 'IntersectionObserver' in window) {
    const io = new IntersectionObserver((ents) => { if (ents.some((e) => e.isIntersecting)) { io.disconnect(); load(); } }, { rootMargin: '200px' });
    io.observe(box);
  }
  el.querySelector('[data-fs]').addEventListener('click', () => {
    load();
    const b = el.querySelector('.sim-box');
    if (b.requestFullscreen) b.requestFullscreen().catch(() => window.open(url, '_blank'));
    else if (b.webkitRequestFullscreen) b.webkitRequestFullscreen();
    else window.open(url, '_blank');
  });
}
